script:
function setupForm(ctx) {
    var draft = ctx.doc.custom_koda_pending_draft;
    if (!draft) {
        return { actions: [] };
    }
    var preview = draft.split(/\n+/).filter(Boolean).join("  •  ");
    return {
        actions: [
            {
                label: "Koda Update",
                onClick: function () {
                    ctx.$dialog({
                        title: "Koda has an update for this ticket",
                        message: preview,
                        actions: [
                            {
                                label: "Copy",
                                variant: "solid",
                                onClick: function ({ close }) {
                                    navigator.clipboard.writeText(draft);
                                    ctx.toast.success("Copied to clipboard");
                                    close();
                                },
                            },
                            {
                                label: "Dismiss",
                                variant: "subtle",
                                onClick: function ({ close }) {
                                    ctx.call("frappe.client.set_value", {
                                        doctype: "HD Ticket",
                                        name: ctx.doc.name,
                                        fieldname: "custom_koda_pending_draft",
                                        value: "",
                                    });
                                    ctx.doc.custom_koda_pending_draft = "";
                                    close();
                                },
                            },
                        ],
                    });
                },
            },
        ],
    };
}
